def f(n):
    """Calculates the largest odd factor of n."""
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(v, u):
    """
    Checks if the condition holds for given v and u.
    The condition is: f(u+v+k) - f(u+k) is a multiple of 4 for k=0 to v-1.
    """
    if v <= 0 or u <= 0:
        return False

    for k in range(v):
        diff = f(u + v + k) - f(u + k)
        if diff % 4 != 0:
            return False
    return True

# Test cases for v = 1, 2, 3, 4 and u = 1 to 20
results = {}
V_values = [1, 2, 3, 4]
U_values = range(1, 21)

for v in V_values:
    found_u = False
    for u in U_values:
        if check_condition(v, u):
            found_u = True
            break
    results[v] = {
        "found_u": found_u,
        "tested_u": U_values # Just to track the scope
    }

print("Results:", results)

def f(n):
    if n <= 0:
        return 0 # Should not happen for positive integers
    while n % 2 == 0:
        n //= 2
    return n

# Test for the smallest u such that f(u+1) - f(u) is a multiple of 4
u = 1
while True:
    diff = f(u + 1) - f(u)
    if diff % 4 == 0:
        print(f"Found smallest u: {u}")
        print(f"f({u+1}) = {f(u+1)}, f({u}) = {f(u)}")
        print(f"Difference: {diff}")
        break
    u += 1
